//#region src/client/Privy.d.ts
/**
 * `PrivyOptions` to setup the `Privy` SDK
 */
type PrivyOptions = {
  /** The `Storage` instance to be used */
  storage: Storage;
  /** The application ID */
  appId: string;
  /** The client ID */
  clientId?: string;
  /** Plugins that extend Privy client behavior. */
  plugins?: readonly PrivyPlugin[];
  /** A reference the the embedded wallet iframe content window */
  embeddedWalletMessagePoster?: EmbeddedWalletMessagePoster;
  /**
   * A list of supported chains, used to specify which chains should be used throughout the application.
   * **Overrides the default list of supported chains.** Calling `sendTransaction` or `switchChain` on
   * an unsupported network will throw an error.
   *
   * For embedded wallets, the wallet will automatically default to the first supplied `supportedChain`.
   */
  supportedChains?: NonEmptyArray<Chain>;
  logger?: Logger;
  /**
   * @experimental
   *
   * Session management configuration.
   */
  sessions?: {
    /**
     * @experimental
     *
     * Controls whether the SDK supports multiple authenticated users on the same device.
     * `'single-user'` - default behavior, one authenticated user at a time.
     * `'multi-user'` - enables switching between saved users without re-authenticating.
     *
     * @default 'single-user'
     */
    mode?: 'single-user' | 'multi-user';
    /**
     * @experimental
     *
     * How to treat the cookie mirror of the session tokens. Cookies are only read by a
     * same-origin server, never by Privy, so `'never'` does not affect auth.
     *
     * @default 'default'
     */
    cookieWriteBehavior?: CookieWriteBehavior;
  };
};
/**
 * Privy API Client SDK
 */
declare class Privy {
  /** Plugins configured for this client instance. */
  readonly plugins: readonly PrivyPlugin[];
  /**
   * APIs for interacting with a user's embedded wallet
   */
  readonly auth: AuthApi;
  /**
   * APIs for fetching user data
   */
  readonly user: UserApi;
  /**
   * APIs for interacting with a user's embedded wallet
   */
  readonly embeddedWallet: EmbeddedWalletApi;
  /**
   * APIs for recovery auth with OAuth
   */
  readonly recovery: RecoveryApi;
  /**
   * APIs for MFA auth
   */
  readonly mfa: MfaApi;
  /**
   * APIs for App configurations
   */
  readonly app: AppApi;
  /**
   * Promises for MFA flows
   */
  readonly mfaPromises: MfaPromises;
  /**
   * APIs for Funding
   */
  readonly funding: FundingApi;
  /**
   * APIs for Wallet Delegated Actions
   */
  readonly delegated: DelegatedWalletsApi;
  /**
   * APIs for Cross App Connections
   */
  readonly crossApp: CrossAppApi;
  /**
   * @experimental
   *
   * Whether multi-user session mode is enabled.
   */
  readonly isMultiUserModeEnabled: boolean;
  /** Create a new `Privy` Client */
  constructor({ clientId, sessions, plugins, ...o }: PrivyOptions);
  /**
   * Initialize the SDK
   *
   * @returns void
   * @throws if there are errors
   */
  initialize(): Promise<void>;
  setMessagePoster(poster: EmbeddedWalletMessagePoster): void;
  getAccessToken(): Promise<string | null>;
  getIdentityToken(): Promise<string | null>;
  track({ name, properties }: {
    name: string;
    properties: object;
  }): void;
  getCompiledPath<const T extends Route<U, V>, const U, const V>(r: T, opts: {
    body?: T['body'];
    params?: Record<string, string | number>;
    headers?: HeadersInit;
  }): string;
  fetchPrivyRoute<const T extends Route<U, V>, const U, const V>(r: T, opts: {
    body?: T['body'];
    query?: Record<string, string | number>;
    params?: Record<string, string | number>;
    headers?: HeadersInit;
    /** Aborts the request. The built-in timeout still applies. */
    signal?: AbortSignal;
  }): Promise<NonNullable<T['response']>>;
  /**
   * Like {@link fetchPrivyRoute}, but resolves the raw {@link Response} rather than a parsed JSON
   * body — for endpoints whose success payload is not JSON (e.g. a PDF). Applies the same headers,
   * access-token refresh, and timeout as {@link fetchPrivyRoute}; the caller reads the body itself
   * (`.blob()`, `.arrayBuffer()`, …). Throws on a non-2xx status.
   */
  fetchPrivyRouteRaw<const T extends Route<U, V>, const U, const V>(r: T, opts: {
    body?: T['body'];
    query?: Record<string, string | number>;
    params?: Record<string, string | number>;
    headers?: HeadersInit;
  }): Promise<Response>;
  /**
   * Internal logger for the Privy client.
   */
  get logger(): Logger;
}
